+export type OrderInput = {
+  sku: string;
+  quantity: number;
+};
+
+export function validateOrderInput(input: unknown):
+  | { ok: true; value: OrderInput }
+  | { ok: false; error: string } {
+  if (!input || typeof input !== "object") {
+    return { ok: false, error: "payload invalido" };
+  }
+  const data = input as Record<string, unknown>;
+  if (typeof data.sku !== "string" || data.sku.length < 3) {
+    return { ok: false, error: "sku requerido" };
+  }
+  if (typeof data.quantity !== "number" || data.quantity < 1) {
+    return { ok: false, error: "quantity invalida" };
+  }
+  return { ok: true, value: { sku: data.sku, quantity: data.quantity } };
+}
