@@ -0,0 +1,80 @@
+#![no_std]
+use soroban_sdk::{contract, contractimpl, Address, Env, Symbol, Vec};
+
+mod storage;
+mod milestones;
+mod errors;
+
+use storage::{EscrowData, write_escrow, read_escrow};
+use milestones::{Milestone, add_milestone, mark_released};
+use errors::EscrowError;
+
+#[contract]
+pub struct EscrowContract;
+
+#[contractimpl]
+impl EscrowContract {
+    pub fn create(env: Env, payer: Address, payee: Address, amount: i128) -> Result<(), EscrowError> {
+        payer.require_auth();
+        if amount <= 0 {
+            return Err(EscrowError::InvalidAmount);
+        }
+        let data = EscrowData {
+            payer: payer.clone(),
+            payee: payee.clone(),
+            amount,
+            released: 0,
+            milestones: Vec::new(&env),
+        };
+        write_escrow(&env, &data);
+        Ok(())
+    }
+
+    pub fn add_milestone_rule(
+        env: Env,
+        payer: Address,
+        label: Symbol,
+        portion: i128,
+    ) -> Result<(), EscrowError> {
+        payer.require_auth();
+        let mut data = read_escrow(&env)?;
+        if data.payer != payer {
+            return Err(EscrowError::Unauthorized);
+        }
+        add_milestone(&env, &mut data, Milestone { label, portion, done: false })?;
+        write_escrow(&env, &data);
+        Ok(())
+    }
+
+    pub fn release_milestone(env: Env, payer: Address, index: u32) -> Result<(), EscrowError> {
+        payer.require_auth();
+        let mut data = read_escrow(&env)?;
+        if data.payer != payer {
+            return Err(EscrowError::Unauthorized);
+        }
+        mark_released(&env, &mut data, index)?;
+        write_escrow(&env, &data);
+        Ok(())
+    }
+
+    pub fn balance(env: Env) -> Result<i128, EscrowError> {
+        let data = read_escrow(&env)?;
+        Ok(data.amount - data.released)
+    }
+}
