+use soroban_sdk::{contracttype, Env, Symbol};
+use crate::storage::EscrowData;
+use crate::errors::EscrowError;
+
+#[contracttype]
+pub struct Milestone {
+    pub label: Symbol,
+    pub portion: i128,
+    pub done: bool,
+}
+
+pub fn add_milestone(
+    env: &Env,
+    data: &mut EscrowData,
+    milestone: Milestone,
+) -> Result<(), EscrowError> {
+    if milestone.portion <= 0 {
+        return Err(EscrowError::InvalidAmount);
+    }
+    let total: i128 = data.milestones.iter().map(|m| m.portion).sum();
+    if total + milestone.portion > data.amount {
+        return Err(EscrowError::InvalidAmount);
+    }
+    data.milestones.push_back(milestone);
+    let _ = env;
+    Ok(())
+}
+
+pub fn mark_released(
+    env: &Env,
+    data: &mut EscrowData,
+    index: u32,
+) -> Result<(), EscrowError> {
+    let mut m = data.milestones.get(index).ok_or(EscrowError::NotFound)?;
+    if m.done {
+        return Err(EscrowError::AlreadyReleased);
+    }
+    m.done = true;
+    data.released += m.portion;
+    data.milestones.set(index, m);
+    let _ = env;
+    Ok(())
+}
