+export type ReportRow = { label: string; value: number };
+
+export function buildSummary(rows: ReportRow[]): {
+  total: number;
+  labels: string[];
+} {
+  const total = rows.reduce((acc, row) => acc + row.value, 0);
+  return {
+    total,
+    labels: rows.map((r) => r.label),
+  };
+}
+
+export function formatSummary(rows: ReportRow[]): string {
+  const summary = buildSummary(rows);
+  return `total=${summary.total}; n=${summary.labels.length}`;
+}
